-- AprovaQuest V1 — schema + políticas + dados iniciais
create extension if not exists pgcrypto;

create table if not exists public.usuarios (
  id uuid primary key references auth.users(id) on delete cascade,
  nome text,
  email text,
  is_admin boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists public.assuntos (
  id bigint generated by default as identity primary key,
  materia text not null,
  nome text not null,
  slug text not null,
  descricao text not null default '',
  created_at timestamptz not null default now(),
  unique (materia, slug)
);

create table if not exists public.questoes (
  id bigint generated by default as identity primary key,
  materia text not null,
  assunto text not null,
  dificuldade text not null check (dificuldade in ('Fácil','Médio','Difícil')),
  titulo text not null,
  slug text not null unique,
  enunciado text not null,
  alternativa_a text not null,
  alternativa_b text not null,
  alternativa_c text not null,
  alternativa_d text not null,
  alternativa_e text not null,
  resposta_correta text not null check (resposta_correta in ('A','B','C','D','E')),
  explicacao text not null,
  dica text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists questoes_materia_idx on public.questoes(materia);
create index if not exists questoes_assunto_idx on public.questoes(assunto);
create index if not exists questoes_dificuldade_idx on public.questoes(dificuldade);

create or replace function public.set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists questoes_set_updated_at on public.questoes;
create trigger questoes_set_updated_at before update on public.questoes
for each row execute function public.set_updated_at();

alter table public.questoes enable row level security;
alter table public.assuntos enable row level security;
alter table public.usuarios enable row level security;

drop policy if exists "public read questoes" on public.questoes;
create policy "public read questoes" on public.questoes for select using (true);

drop policy if exists "public read assuntos" on public.assuntos;
create policy "public read assuntos" on public.assuntos for select using (true);

drop policy if exists "admins insert questoes" on public.questoes;
create policy "admins insert questoes" on public.questoes for insert to authenticated
with check (exists (select 1 from public.usuarios u where u.id=auth.uid() and u.is_admin=true));

drop policy if exists "admins update questoes" on public.questoes;
create policy "admins update questoes" on public.questoes for update to authenticated
using (exists (select 1 from public.usuarios u where u.id=auth.uid() and u.is_admin=true))
with check (exists (select 1 from public.usuarios u where u.id=auth.uid() and u.is_admin=true));

drop policy if exists "admins delete questoes" on public.questoes;
create policy "admins delete questoes" on public.questoes for delete to authenticated
using (exists (select 1 from public.usuarios u where u.id=auth.uid() and u.is_admin=true));

-- O público não precisa ler a tabela usuarios.
drop policy if exists "users read own profile" on public.usuarios;
create policy "users read own profile" on public.usuarios for select to authenticated
using (id=auth.uid());

