-- 3) Execute:
-- insert into public.usuarios (id,nome,email,is_admin)
-- values ('UUID-DO-USUARIO','Administrador','seu-email@exemplo.com',true)
-- on conflict (id) do update set is_admin=true, email=excluded.email, nome=excluded.nome;
